it('hypothesis Math.round', () => {
  const orig = dayjs.prototype.tz
  dayjs.prototype.tz = function (timezone) {
    const target = this.toDate().toLocaleString('en-US', { timeZone: timezone })
    const diff = Math.round((this.toDate() - new Date(target)) / 1000 / 60)
    return dayjs(target).utcOffset(dayjs().utcOffset() - diff, true)
  }
  const rows = []
  zones.forEach((z) => instants.forEach((i) => {
    const d = dayjs(i).tz(z)
    const m = moment(i).tz(z)
    const dv = [d.format(), d.format('Z'), d.format('ZZ'), d.utcOffset(), d.valueOf()]
    const mv = [m.format(), m.format('Z'), m.format('ZZ'), m.utcOffset(), m.valueOf()]
    ;['format', 'formatZ', 'formatZZ', 'utcOffset', 'valueOf'].forEach((f, k) => {
      if (dv[k] !== mv[k]) rows.push(`${z} | ${i} | ${f} | dayjs=${dv[k]} | moment=${mv[k]}`)
    })
  }))
  console.log(`HYPOTHESIS-Math.round TZ=${process.env.TZ} mismatchCount=${rows.length}`)
  console.log(rows.join('\n'))
  dayjs.prototype.tz = orig
  expect(true).toBe(true)
})

